    private void jButton5ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton5ActionPerformed
        personal.busquedaPorCINombre(jTable1, txtbusqueda.getText());
    }//GEN-LAST:event_jButton5ActionPerformed

    private void jButton6ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton6ActionPerformed
        int fila = jTable1.getSelectedRow();
        if (fila > -1) {
            String idPersona = jTable1.getValueAt(fila, 0).toString();
            if (FormPrincipal.FormUsuario.isVisible()) {
                FormPrincipal.FormUsuario.txtCIPersonal.setText(idPersona);
            }
            if(FormPrincipal.FormInscripcion.isVisible()) {
                FormPrincipal.FormInscripcion.txtIDPersona.setText(idPersona);
            }
            this.dispose();
        }
    }//GEN-LAST:event_jButton6ActionPerformed

