    private void jTable1MouseReleased(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_jTable1MouseReleased
        int fila = jTable1.getSelectedRow();
        if (fila > -1) {
            String idPersona = jTable1.getValueAt(fila, 0).toString();
            if (FormPrincipal.FormUsuario.isVisible()) {
                FormPrincipal.FormUsuario.txtCIPersonal.setText(idPersona);
            }
            if(FormPrincipal.FormInscripcion.isVisible()) {
                FormPrincipal.FormInscripcion.txtIDPersona.setText(idPersona);
            }
            this.dispose();
        }
    }//GEN-LAST:event_jTable1MouseReleased

